4702: # (subscription | api-key); auth_method and api_provider as `claude auth status` reported them in
4703: # this process (the preflight), $null when it did not run. (wave 29b, E5) auth endpoint:
4704: # credential_mechanism endpoint, base_url (as the roster names it - not a secret), env_key (the
4705: # variable's NAME - the token never appears) and plan (the entry's plan slug, $null without one).
4706: function Get-ClaudeIdentityConfig {
4707:     param([string]$Auth = 'subscription', [string]$Launcher = '', $Endpoint = $null)
4708:     if ($script:ClaudeAuthModes -notcontains $Auth) { $Auth = 'subscription' }
4709:     if ($Auth -eq 'endpoint') {
4710:         $e = [ordered]@{}
4711:         $e['credential_mechanism'] = 'endpoint'
4712:         $e['base_url'] = $(if ($Endpoint) { [string]$Endpoint.BaseUrl } else { $null })
4713:         $e['env_key'] = $(if ($Endpoint) { [string]$Endpoint.EnvKey } else { $null })
4714:         $e['plan'] = $(if ($Endpoint -and [string](Get-PropertyValue $Endpoint 'Plan' '')) { [string]$Endpoint.Plan } else { $null })
4715:         return $e
4716:     }
4717:     $c = $null
4718:     if ($script:ClaudeSignInCache.ContainsKey("$Launcher|$Auth")) { $c = $script:ClaudeSignInCache["$Launcher|$Auth"] }
4719:     $o = [ordered]@{}
4720:     $o['credential_mechanism'] = $Auth
4721:     $o['auth_method'] = $(if ($c -and $c.AuthMethod) { $c.AuthMethod } else { $null })
4722:     $o['api_provider'] = $(if ($c -and $c.ApiProvider) { $c.ApiProvider } else { $null })
4723:     return $o
4724: }
4725: 
4726: # (item 2) Where the engine keeps its transcripts must not lie in the repository under review (the
4727: # strict tree check would fail every run): CLAUDE_CONFIG_DIR, and the projectsDirectory the sign-in
4728: # check read. '' or the refusal.
4729: function Get-ClaudeLaunchProblem {
4730:     param([string]$RepoRoot, [string]$Launcher = '', [string]$Auth = 'subscription')
4731:     if (-not $RepoRoot) { return '' }
4732:     $cfg = [string][Environment]::GetEnvironmentVariable('CLAUDE_CONFIG_DIR')
4733:     if ($cfg.Trim()) { try { if ($null -ne (Get-RepoRelativePath -Root $RepoRoot -Path $cfg.Trim())) { return "CLAUDE_CONFIG_DIR ($($cfg.Trim())) lies inside the repository under review: the engine's transcripts would change the tree; point it elsewhere" } } catch { } }
4734:     $key = "$Launcher|$Auth"
4735:     if ($script:ClaudeSignInCache.ContainsKey($key)) {
4736:         $pd = [string]$script:ClaudeSignInCache[$key].ProjectsDirectory
4737:         if ($pd.Trim()) { try { if ($null -ne (Get-RepoRelativePath -Root $RepoRoot -Path $pd.Trim())) { return "the claude projectsDirectory ($($pd.Trim())) lies inside the repository under review: the engine's transcripts would change the tree" } } catch { } }
4738:     }
4739:     return ''
4740: }
4741: 
4742: # reviewer.harness of a claude run (item 6): "claude-cli <version>" from the launcher's file
4743: # metadata (the native claude.exe carries it), else `<launcher> --version` in the child environment
4744: # (an npm shim; local, no request spent; 15 s), else "claude-cli (version unknown)". Cached per
4745: # launcher.
4746: $script:ClaudeHarnessCache = @{}
4747: $script:ClaudeVersionRe = '^v?[0-9]+\.[0-9]+[0-9A-Za-z.+_-]{0,48}$'
4748: function Get-ClaudeHarness {
4749:     param([string]$Launcher)
4750:     if (-not $Launcher) { return 'claude-cli (version unknown)' }
4751:     if ($script:ClaudeHarnessCache.ContainsKey($Launcher)) { return $script:ClaudeHarnessCache[$Launcher] }
4752:     $ver = ''
4753:     try { $ver = ([string](Get-Item -LiteralPath $Launcher -ErrorAction Stop).VersionInfo.ProductVersion).Trim() } catch { $ver = '' }
4754:     if ($ver -notmatch $script:ClaudeVersionRe) {
4755:         $ver = ''
4756:         $cap = Invoke-ClaudeProbe -Launcher $Launcher -Arguments '--version' -TimeoutSec 15
4757:         if ($cap.Started -and -not $cap.TimedOut -and $cap.Exit -eq 0) {
4758:             foreach ($tok in @(($cap.Out + "`n" + $cap.Err) -split '\s+')) { if ($tok -match $script:ClaudeVersionRe) { $ver = $tok; break } }
4759:         }
4760:     }
4761:     $h = $(if ($ver) { "claude-cli $($ver -replace '^v', '')" } else { 'claude-cli (version unknown)' })
4762:     $script:ClaudeHarnessCache[$Launcher] = $h
4763:     return $h
4764: }

