7681: # (wave 29b, E5) THE PLAN identity (quota). A roster entry's optional `plan` names the coding plan
7682: # whose quota its route spends - the same plan can be reached on several routes (z.ai through codex
7683: # as ZAI and through the claude engine as ZAI-claude). The health records of EVERY route of the plan (the
7684: # fingerprints of the roster's entries with that plan) are read as one record set
7685: # (Get-EndpointHealth -Fingerprints): when its newest {usable reply, quota failure} is a quota
7686: # failure that still blocks (a usage limit with a reset ahead, or without one for 60 minutes, a
7687: # burst for 10), the plan is out until that time. Auth, transport and capability failures stay
7688: # route-local; without a `plan` nothing propagates. { Plan; Quota (the blocking record, with its
7689: # Fingerprint; $null); QuotaKnown; Label (the provider label of the route it was recorded on - the
7690: # first roster entry of the plan on that fingerprint) }. Cached in a listing cache per plan and clock.
7691: function Get-PlanQuota {
7692:     param($Roster, [string]$Plan, $Config, [object[]]$Consults, [string]$Launcher = '', [hashtable]$EngineLaunchers = $null, [datetime]$UtcNow = [datetime]::UtcNow, [string]$OpenAiBaseUrl = '', [hashtable]$Cache = $null)
7693:     $use = Test-ListingCache $Cache
7694:     $key = Get-ListingCacheKey @('plan', $Plan, [string]$UtcNow.Ticks)
7695:     if ($use -and $Cache.ContainsKey($key)) { return $Cache[$key] }
7696:     $r = [pscustomobject]@{ Plan = $Plan; Quota = $null; QuotaKnown = $false; Label = '' }
7697:     $labelOf = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
7698:     $fps = New-Object System.Collections.Generic.List[string]
7699:     foreach ($e in @(@($Roster.Entries) | Where-Object { $_ -and [string](Get-PropertyValue $_ 'Plan' '') -ceq $Plan })) {
7700:         $eng = $(if ([string](Get-PropertyValue $e 'Engine' '')) { [string]$e.Engine } else { 'codex' })
7701:         $lau = Get-EngineLauncher -Engine $eng -Launchers $EngineLaunchers -CodexLauncher $Launcher
7702:         $id = Get-CachedReviewerIdentity -Cache $Cache -Config $Config -Provider ([string]$e.Provider) -Model ([string]$e.Model) -OpenAiBaseUrl $OpenAiBaseUrl -Engine $eng -Launcher $lau -Auth ([string]$e.Auth) -Endpoint (Get-PropertyValue $e 'Endpoint' $null)
7703:         if (-not $id.Resolved -or -not $id.Fingerprint) { continue }
7704:         if (-not $labelOf.ContainsKey([string]$id.Fingerprint)) { $labelOf[[string]$id.Fingerprint] = [string]$e.Provider; $fps.Add([string]$id.Fingerprint) }
7705:     }
7706:     if ($fps.Count -gt 0) {
7707:         $h = Get-EndpointHealth -Consults $Consults -Fingerprints ([string[]]$fps.ToArray()) -UtcNow $UtcNow
7708:         if ($h.Quota) {
7709:             $r.Quota = $h.Quota
7710:             $r.QuotaKnown = $h.QuotaKnown
7711:             $r.Label = [string]$labelOf[[string]$h.Quota.Fingerprint]
7712:         }
7713:     }
7714:     if ($use) { $Cache[$key] = $r }
7715:     return $r
7716: }
7717: 
7718: # (wave 29b, E5) A preflight verdict ($Verdict: Get-PreflightVerdict's for $Identity) with the plan
7719: # quota of its roster entry applied: an entry whose own verdict is available or not checked is OUT
7720: # when its plan is (Get-PlanQuota) on ANOTHER route - "plan <slug> (usage limit on <label> until
7721: # <iso>)", or without a reset time "plan <slug> (usage limit on <label> hit <iso>, reset unknown;
7722: # retry after <iso>)"; Kind quota | quota-unknown-reset, Hit and Until of that record, PlanQuota {
7723: # Plan; Label } for the availability views. Any other verdict, an entry without a plan, a plan with
7724: # no blocking record (or one recorded on this entry's own route - its own verdict says it): $Verdict
7725: # unchanged.
7726: function Get-PlanQuotaVerdict {
7727:     param($Verdict, $Entry, $Identity, $Roster, $Config, [object[]]$Consults, [string]$Launcher = '', [hashtable]$EngineLaunchers = $null, [datetime]$UtcNow = [datetime]::UtcNow, [string]$OpenAiBaseUrl = '', [hashtable]$Cache = $null, [switch]$RosterWalk)
7728:     $plan = [string](Get-PropertyValue $Entry 'Plan' '')
7729:     if (-not $plan -or -not $Verdict -or -not $Roster) { return $Verdict }
7730:     if (-not ($Verdict.State -eq 'available' -or ($Verdict.State -eq 'unknown' -and $Verdict.Kind -eq 'unknown'))) { return $Verdict }
7731:     $pq = Get-PlanQuota -Roster $Roster -Plan $plan -Config $Config -Consults $Consults -Launcher $Launcher -EngineLaunchers $EngineLaunchers -UtcNow $UtcNow -OpenAiBaseUrl $OpenAiBaseUrl -Cache $Cache
7732:     if (-not $pq.Quota) { return $Verdict }
7733:     $ownFp = $(if ($Identity -and $Identity.Resolved) { [string]$Identity.Fingerprint } else { '' })
7734:     if ($ownFp -and [string]$pq.Quota.Fingerprint -eq $ownFp) { return $Verdict }
7735:     $q = $pq.Quota
7736:     $on = $(if ($pq.Label) { $pq.Label } else { 'another route' })
7737:     $p = [string]$Identity.Provider
7738:     $v = [pscustomobject]@{ State = 'unavailable'; Preflight = ''; Reason = ''; Refusal = ''; Label = ''; Kind = ''; Hit = $q.Hit; Until = $null; Credential = $Verdict.Credential; Burst = $false; PlanQuota = [pscustomobject]@{ Plan = $plan; Label = $on } }
7739:     if ($pq.QuotaKnown) {
7740:         $v.Kind = 'quota'
7741:         $v.Until = $q.RetryAfter
7742:         $v.Reason = "plan $plan (usage limit on $on until $($q.RetryAfterIso))"
7743:         $v.Refusal = "provider $p is not usable: its plan $plan hit a usage limit on $on at $($q.When) ($($q.Message)) that lasts until $($q.RetryAfterIso); nothing was started$(if (-not $RosterWalk) { ' (pass -SkipPreflight to launch anyway)' })"
7744:     } else {
7745:         $v.Kind = 'quota-unknown-reset'
7746:         $v.Burst = ([string](Get-PropertyValue $q 'FailureKind' '') -eq 'burst')
7747:         $v.Until = $q.Until
7748:         $untilIso = Format-OffsetIso $q.Until
7749:         $what = $(if ($v.Burst) { 'burst limit (429)' } else { 'usage limit' })
7750:         $v.Reason = "plan $plan ($what on $on hit $($q.HitIso), reset unknown; retry after $untilIso)"
7751:         $v.Refusal = "provider $p is not usable: its plan $plan hit a $(if ($v.Burst) { 'burst' } else { 'usage' }) limit on $on at $($q.HitIso) ($($q.Message)) and named no reset time - out until $untilIso; nothing was started$(if (-not $RosterWalk) { ' (pass -SkipPreflight to launch anyway)' })"
7752:     }
7753:     $v.Preflight = "unavailable: $($v.Reason)"
7754:     $v.Label = "unavailable ($($v.Reason)) - a real run is refused: $($v.Refusal)"
7755:     return $v
7756: }
7757: 
7758: # The warning of a usage limit that does not refuse the run - with -SkipPreflight only (wave 24b,
7759: # F08-7: without it every usage limit that still blocks refuses the run, Get-PreflightVerdict):
7760: # one whose reset time lies ahead, or one without a reset time hit less than 60 minutes ago. ''
7761: # otherwise.
7762: function Format-QuotaWarning {
8607: # member with a roster `plan` adds the key 'plan:<slug>' - the members of one plan share a group
8608: # across engines and routes (a codex ZAI member and a claude ZAI-claude member serialize); the
8609: # availability view does not group by plan (E5: only a quota failure propagates over a plan).
8610: function Get-EndpointGroups {
8611:     param([object[]]$Members, [switch]$Scheduling)
8612:     $labels = New-Object System.Collections.Generic.List[string]
8613:     $fps = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
8614:     foreach ($m in @($Members | Where-Object { $_ })) {
8615:         $label = [string]$m.Entry.Provider
8616:         if (-not $fps.ContainsKey($label)) { $fps[$label] = New-Object System.Collections.Generic.List[string]; $labels.Add($label) }
8617:         $fp = ''
8618:         if ($m.Identity -and $m.Identity.Resolved) { $fp = [string]$m.Identity.Fingerprint }
8619:         if ($fp -and -not $fps[$label].Contains($fp)) { $fps[$label].Add($fp) }
8620:         if ($Scheduling) {
8621:             $mEngine = [string](Get-PropertyValue $m.Entry 'Engine' '')
8622:             $mSpec = $(if ($mEngine) { Get-EngineSpec -Name $mEngine } else { $null })
8623:             if ($mSpec -and [string](Get-PropertyValue $mSpec 'ParallelScope' '') -eq 'engine' -and -not $fps[$label].Contains("engine:$mEngine")) { $fps[$label].Add("engine:$mEngine") }
8624:             $mPlan = [string](Get-PropertyValue $m.Entry 'Plan' '')
8625:             if ($mPlan -and -not $fps[$label].Contains("plan:$mPlan")) { $fps[$label].Add("plan:$mPlan") }
8626:         }
8627:     }
8628:     # one group per label, then labels that share a fingerprint are merged (to a fixed point)
8629:     $groupOfLabel = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
8630:     for ($i = 0; $i -lt $labels.Count; $i++) { $groupOfLabel[$labels[$i]] = $i }
8631:     $changed = $true
8632:     while ($changed) {
8633:         $changed = $false
8634:         for ($i = 0; $i -lt $labels.Count; $i++) {
8635:             for ($j = $i + 1; $j -lt $labels.Count; $j++) {
8636:                 $gi = $groupOfLabel[$labels[$i]]; $gj = $groupOfLabel[$labels[$j]]
8637:                 if ($gi -eq $gj) { continue }
8638:                 $shared = @($fps[$labels[$i]] | Where-Object { $fps[$labels[$j]].Contains($_) }).Count -gt 0
8639:                 if (-not $shared) { continue }
8640:                 $keep = [Math]::Min($gi, $gj); $drop = [Math]::Max($gi, $gj)
8641:                 foreach ($l in $labels) { if ($groupOfLabel[$l] -eq $drop) { $groupOfLabel[$l] = $keep } }
8642:                 $changed = $true
8643:             }
8644:         }
8645:     }
8646:     $groups = New-Object System.Collections.Generic.List[object]
8647:     $indexOf = @{}
8648:     $groupOf = @{}
8649:     foreach ($m in @($Members | Where-Object { $_ })) {
8650:         $label = [string]$m.Entry.Provider
8651:         $gid = $groupOfLabel[$label]
8652:         if (-not $indexOf.ContainsKey($gid)) {
8653:             $indexOf[$gid] = $groups.Count
8654:             $groups.Add([pscustomobject]@{ Labels = (New-Object System.Collections.Generic.List[string]); Positions = (New-Object System.Collections.Generic.List[int]) })
8655:         }
8656:         $g = $groups[$indexOf[$gid]]
8657:         if (-not $g.Labels.Contains($label)) { $g.Labels.Add($label) }
8658:         $g.Positions.Add([int]$m.Entry.Position)
8659:         $groupOf[[int]$m.Entry.Position] = $indexOf[$gid]
8660:     }
8661:     $indexOfLabel = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
8662:     foreach ($l in $labels) { $indexOfLabel[$l] = $indexOf[$groupOfLabel[$l]] }
8663:     return [pscustomobject]@{ Labels = [string[]]$labels.ToArray(); Groups = [object[]]$groups.ToArray(); GroupOf = $groupOf; IndexOfLabel = $indexOfLabel }
8664: }
8665: 
8666: # The concurrency plan of a panel (0.4.x wave 21, D8 - endpoint-aware): members that reach the
8667: # same ENDPOINT run one after another, members of different endpoints at once. The endpoint
8668: # groups come from Get-EndpointGroups over the runners. A group runs 1 member at a time unless
8669: # the roster's top-level "parallel" raises its label (a merged group: the smallest limit of its
8670: # labels); -Cap (-PanelConcurrency) caps the total (0 = no cap, 1 = strictly one after another
8671: # in roster order). $Runners: the members Select-PanelMembers runs (State 'run'), in roster
8672: # order.
8673: # (wave 29b, E7) A group that holds members of a `plan` is limited by the plan too: the plan's own
