8681: function Get-PanelPlan {
8682:     param([object[]]$Runners, [hashtable]$Parallel = $null, [int]$Cap = 0)
8683:     $eg = Get-EndpointGroups -Members $Runners -Scheduling
8684:     $effective = 0
8685:     $limits = [ordered]@{}
8686:     $out = New-Object System.Collections.Generic.List[object]
8687:     # (E7) the plans of each label among the runners
8688:     $plansOf = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
8689:     foreach ($m in @($Runners | Where-Object { $_ })) {
8690:         $pl = [string](Get-PropertyValue $m.Entry 'Plan' '')
8691:         $lb = [string]$m.Entry.Provider
8692:         if (-not $plansOf.ContainsKey($lb)) { $plansOf[$lb] = New-Object System.Collections.Generic.List[string] }
8693:         if ($pl -and -not $plansOf[$lb].Contains($pl)) { $plansOf[$lb].Add($pl) }
8694:     }
8695:     $planLimit = { param([string]$P) if ($null -ne $Parallel -and $Parallel.ContainsKey($P)) { [int]$Parallel[$P] } else { 1 } }
8696:     foreach ($g in $eg.Groups) {
8697:         $limit = 0
8698:         foreach ($l in $g.Labels) {
8699:             $v = 1
8700:             $lPlans = $(if ($plansOf.ContainsKey($l)) { @($plansOf[$l]) } else { @() })
8701:             if ($null -ne $Parallel -and $Parallel.ContainsKey($l)) { $v = [int]$Parallel[$l] }
8702:             elseif ($lPlans.Count -gt 0) { $v = [int](@($lPlans | ForEach-Object { & $planLimit $_ }) | Measure-Object -Minimum).Minimum }
8703:             if ($limit -eq 0 -or $v -lt $limit) { $limit = $v }
8704:             foreach ($pl in $lPlans) { $pv = & $planLimit $pl; if ($pv -lt $limit) { $limit = $pv } }
8705:         }
8706:         $effective += [Math]::Min($limit, $g.Positions.Count)
8707:         $out.Add([pscustomobject]@{ Labels = [string[]]$g.Labels.ToArray(); Limit = $limit; Positions = [int[]]$g.Positions.ToArray() })
8708:     }
8709:     foreach ($l in $eg.Labels) { $limits[$l] = $out[$eg.IndexOfLabel[$l]].Limit }
8710:     if ($Cap -gt 0 -and $Cap -lt $effective) { $effective = $Cap }
8711:     $count = @($Runners | Where-Object { $_ }).Count
8712:     $text = if ($effective -ge $count) { 'at once' } elseif ($effective -le 1) { 'one after another' } else { "at most $effective at a time" }
8713:     return [pscustomobject]@{ Groups = [object[]]$out.ToArray(); GroupOf = $eg.GroupOf; Cap = $Cap; Effective = $effective; Text = $text; Limits = $limits }
8714: }
